mapper.select:
select count(file_id) from data_file_status

	platform=#{platform}

		and analysis_date like '%' #{analysis_date} '%'


		and subbarcode =#{subbarcode}


		and product_name =#{product_name}

select file_id,file_path,file_name,data_type,file_type,file_text,analysis_date,analyzer,barcode,subbarcode,product_name,platform,status,message,created_by,created_date,update_by,update_date
from data_file_status

	platform=#{platform}

		and analysis_date like '%' #{analysis_date} '%'


		and subbarcode =#{subbarcode}


		and product_name =#{product_name}


limit #{pageNo},#{pageSize}

mapper.update:
update analysis_report set status=#{status}

	,bioinfo_checker=#{bioinfo_checker},bioinfo_check_time=sysdate()


	,report_checker=#{report_checker},report_check_time=sysdate()


	,report_sender=#{report_sender},report_send_time=sysdate()

 where report_id=#{report_id}
